#property indicator_separate_window
#property indicator_buffers 2
#property indicator_plots   1

#property indicator_label1  "RSI"
#property indicator_type1   DRAW_LINE
#property indicator_color1  clrDodgerBlue
#property indicator_width1  2

input int InpRSIPeriod = 14;
input ENUM_APPLIED_PRICE InpAppliedPrice = PRICE_CLOSE;

double RSIBuffer[];
double PriceBuffer[];

int rsi_handle = INVALID_HANDLE;

//+------------------------------------------------------------------+
//| Custom indicator initialization function                         |
//+------------------------------------------------------------------+
int OnInit()
{
   SetIndexBuffer(0, RSIBuffer, INDICATOR_DATA);
   ArraySetAsSeries(RSIBuffer, true);

   IndicatorSetString(INDICATOR_SHORTNAME, "RSI(" + IntegerToString(InpRSIPeriod) + ")");

   rsi_handle = iRSI(_Symbol, _Period, InpRSIPeriod, InpAppliedPrice);
   if(rsi_handle == INVALID_HANDLE)
   {
      Print("Failed to create RSI handle. Error: ", GetLastError());
      return(INIT_FAILED);
   }

   return(INIT_SUCCEEDED);
}

//+------------------------------------------------------------------+
//| Custom indicator iteration function                               |
//+------------------------------------------------------------------+
int OnCalculate(const int rates_total,
                const int prev_calculated,
                const int begin,
                const double &price[])
{
   if(rates_total <= InpRSIPeriod)
      return(0);

   if(CopyBuffer(rsi_handle, 0, 0, rates_total, RSIBuffer) <= 0)
   {
      Print("Failed to copy RSI buffer. Error: ", GetLastError());
      return(prev_calculated);
   }

   return(rates_total);
}

//+------------------------------------------------------------------+
//| Custom indicator deinitialization function                       |
//+------------------------------------------------------------------+
